SELECT p.name,COUNT(m.id) recorded_matches,COALESCE(SUM(m.winner=p.id AND m.loser_rank BETWEEN 1 AND 10),0) wins,COALESCE(SUM(m.loser=p.id AND m.winner_rank BETWEEN 1 AND 10),0) losses,COALESCE(SUM(CASE WHEN m.winner=p.id THEN m.loser_rank IS NULL OR m.loser_rank<=0 WHEN m.loser=p.id THEN m.winner_rank IS NULL OR m.winner_rank<=0 ELSE 0 END),0) missing_rank FROM players p LEFT JOIN matches m ON m.winner=p.id OR m.loser=p.id WHERE p.highest_rank=1 GROUP BY p.id,p.name